void AnimationUndoHistory::clear(){undo_.clear();redo_.clear();}void AnimationUndoHistory::record(const teya::animation::AnimationAsset&b){if(capacity_==0)return;if(undo_.size()==capacity_)undo_.erase(undo_.begin());undo_.push_back(b);redo_.clear();}bool AnimationUndoHistory::undo(teya::animation::AnimationAsset&c){if(undo_.empty())return false;if(redo_.size()==capacity_)redo_.erase(redo_.begin());redo_.push_back(c);c=std::move(undo_.back());undo_.pop_back();return true;}bool AnimationUndoHistory::redo(teya::animation::AnimationAsset&c){if(redo_.empty())return false;if(undo_.size()==capacity_)undo_.erase(undo_.begin());undo_.push_back(c);c=std::move(redo_.back());redo_.pop_back();return true;}bool AnimationUndoHistory::canUndo()const{return!undo_.empty();}bool AnimationUndoHistory::canRedo()const{return!redo_.empty();}
void AnimationDocument::load(teya::animation::AnimationAsset a,std::uint64_t id){asset_=std::move(a);assetId_=id;selection_={};history_.clear();dirty_=temporary_=false;++revision_;repairSelection();}void AnimationDocument::markSaved(){dirty_=temporary_=false;}bool AnimationDocument::dirty()const{return dirty_;}bool AnimationDocument::temporaryApplied()const{return temporary_;}void AnimationDocument::markTemporaryApplied(){temporary_=true;}teya::animation::AnimationAsset& AnimationDocument::asset(){return asset_;}const teya::animation::AnimationAsset& AnimationDocument::asset()const{return asset_;}AnimationSelection& AnimationDocument::selection(){return selection_;}const AnimationSelection& AnimationDocument::selection()const{return selection_;}void AnimationDocument::mutate(const teya::animation::AnimationAsset&before){history_.record(before);dirty_=true;temporary_=false;++revision_;repairSelection();}bool AnimationDocument::undo(){bool ok=history_.undo(asset_);if(ok){dirty_=true;++revision_;repairSelection();}return ok;}bool AnimationDocument::redo(){bool ok=history_.redo(asset_);if(ok){dirty_=true;++revision_;repairSelection();}return ok;}
void AnimationDocument::repairSelection(){if(asset_.clips.empty()){selection_={};return;}selection_.clip=std::min(selection_.clip,asset_.clips.size()-1);auto&c=asset_.clips[selection_.clip];selection_.frame=c.frames.empty()?0:std::min(selection_.frame,c.frames.size()-1);auto count=[&](){if(c.frames.empty())return size_t(0);auto&f=c.frames[selection_.frame];switch(selection_.kind){case AnimationSelection::Kind::Socket:return f.sockets.size();case AnimationSelection::Kind::Event:return f.events.size();case AnimationSelection::Kind::Hitbox:return f.hitboxes.size();case AnimationSelection::Kind::Marker:return f.markers.size();default:return size_t(1);}}();selection_.item=count?std::min(selection_.item,count-1):0;}
bool AnimationDocument::addClip(std::string n){if(n.empty()||asset_.findClip(n))return false;auto before=asset_;asset_.clips.push_back({std::move(n),true,{teya::animation::AnimationFrame{}}});selection_.clip=asset_.clips.size()-1;selection_.frame=0;mutate(before);return true;}bool AnimationDocument::duplicateClip(){if(asset_.clips.empty())return false;auto before=asset_;auto copy=asset_.clips[selection_.clip];std::string base=copy.name+"_copy";copy.name=base;for(int i=2;asset_.findClip(copy.name);++i)copy.name=base+std::to_string(i);asset_.clips.insert(asset_.clips.begin()+selection_.clip+1,std::move(copy));++selection_.clip;mutate(before);return true;}bool AnimationDocument::deleteClip(){if(asset_.clips.empty())return false;auto before=asset_;asset_.clips.erase(asset_.clips.begin()+selection_.clip);mutate(before);return true;}bool AnimationDocument::addFrame(){if(asset_.clips.empty())return false;auto before=asset_;auto&f=asset_.clips[selection_.clip].frames;f.insert(f.begin()+std::min(selection_.frame+1,f.size()),teya::animation::AnimationFrame{});selection_.frame=std::min(selection_.frame+1,f.size()-1);mutate(before);return true;}bool AnimationDocument::duplicateFrame(){if(asset_.clips.empty()||asset_.clips[selection_.clip].frames.empty())return false;auto before=asset_;auto&f=asset_.clips[selection_.clip].frames;f.insert(f.begin()+selection_.frame+1,f[selection_.frame]);++selection_.frame;mutate(before);return true;}bool AnimationDocument::deleteFrame(){if(asset_.clips.empty()||asset_.clips[selection_.clip].frames.empty())return false;auto before=asset_;auto&f=asset_.clips[selection_.clip].frames;f.erase(f.begin()+selection_.frame);mutate(before);return true;}bool AnimationDocument::moveFrame(int d){if(asset_.clips.empty())return false;auto&f=asset_.clips[selection_.clip].frames;if(f.empty())return false;auto target=static_cast<long long>(selection_.frame)+d;if(target<0||target>=static_cast<long long>(f.size()))return false;auto before=asset_;std::swap(f[selection_.frame],f[static_cast<size_t>(target)]);selection_.frame=static_cast<size_t>(target);mutate(before);return true;}
void AnimationDocument::copySelection(){if(asset_.clips.empty())return;auto&c=asset_.clips[selection_.clip];if(selection_.kind==AnimationSelection::Kind::Frame&&selection_.frame<c.frames.size())clipboard_=c.frames[selection_.frame];else if(selection_.frame<c.frames.size()){auto&f=c.frames[selection_.frame];if(selection_.kind==AnimationSelection::Kind::Socket&&selection_.item<f.sockets.size())clipboard_=f.sockets[selection_.item];if(selection_.kind==AnimationSelection::Kind::Event&&selection_.item<f.events.size())clipboard_=f.events[selection_.item];if(selection_.kind==AnimationSelection::Kind::Hitbox&&selection_.item<f.hitboxes.size())clipboard_=f.hitboxes[selection_.item];if(selection_.kind==AnimationSelection::Kind::Marker&&selection_.item<f.markers.size())clipboard_=f.markers[selection_.item];}}
bool AnimationDocument::paste(){if(asset_.clips.empty())return false;auto&c=asset_.clips[selection_.clip];auto before=asset_;if(auto*x=std::get_if<teya::animation::AnimationFrame>(&clipboard_)){c.frames.insert(c.frames.begin()+std::min(selection_.frame+1,c.frames.size()),*x);++selection_.frame;}else{if(c.frames.empty())return false;auto&f=c.frames[selection_.frame];if(auto*x=std::get_if<teya::animation::AnimationSocket>(&clipboard_))f.sockets.push_back(*x);else if(auto*x=std::get_if<teya::animation::AnimationEvent>(&clipboard_))f.events.push_back(*x);else if(auto*x=std::get_if<teya::animation::AnimationHitbox>(&clipboard_))f.hitboxes.push_back(*x);else if(auto*x=std::get_if<teya::animation::AnimationMarker>(&clipboard_))f.markers.push_back(*x);else return false;}mutate(before);return true;}
template<class T>void propagate(std::vector<teya::animation::AnimationFrame>&frames,const T&value,size_t begin,size_t end,std::vector<T> teya::animation::AnimationFrame::*member){if(frames.empty())return;end=std::min(end,frames.size()-1);for(size_t i=begin;i<=end;++i){auto&items=frames[i].*member;auto found=std::find_if(items.begin(),items.end(),[&](const auto&x){return x.name==value.name;});if(found==items.end())items.push_back(value);else*found=value;}}
void AnimationDocument::propagateSocket(size_t i,size_t b,size_t e){auto&c=asset_.clips[selection_.clip];if(c.frames.empty()||i>=c.frames[selection_.frame].sockets.size())return;auto before=asset_;propagate(c.frames,c.frames[selection_.frame].sockets[i],b,e,&teya::animation::AnimationFrame::sockets);mutate(before);}void AnimationDocument::propagateHitbox(size_t i,size_t b,size_t e){auto&c=asset_.clips[selection_.clip];if(c.frames.empty()||i>=c.frames[selection_.frame].hitboxes.size())return;auto before=asset_;propagate(c.frames,c.frames[selection_.frame].hitboxes[i],b,e,&teya::animation::AnimationFrame::hitboxes);mutate(before);}void AnimationDocument::propagateMarker(size_t i,size_t b,size_t e){auto&c=asset_.clips[selection_.clip];if(c.frames.empty()||i>=c.frames[selection_.frame].markers.size())return;auto before=asset_;propagate(c.frames,c.frames[selection_.frame].markers[i],b,e,&teya::animation::AnimationFrame::markers);mutate(before);}std::uint64_t AnimationDocument::assetId()const{return assetId_;}std::uint64_t AnimationDocument::revision()const{return revision_;}AnimationUndoHistory& AnimationDocument::history(){return history_;}
float snapAnimationValue(float v,bool enabled,float inc)noexcept{return enabled&&std::isfinite(inc)&&inc>0?std::round(v/inc)*inc:v;}Vector2 animationPreviewScreenToLocal(Vector2 s,Vector2 o,Vector2 p,float z,bool left,float w)noexcept{if(!std::isfinite(z)||z<=0)return{};Vector2 local{(s.x-o.x-p.x)/z,(s.y-o.y-p.y)/z};return left?teya::animation::mirrorPoint(local,w):local;}float animationPreviewZoom(bool pixel,bool integer,float requested,float fit)noexcept{float z=requested>0?requested:fit;if(pixel&&integer)z=std::max(1.0f,std::floor(z));return std::max(.05f,z);}
